using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Reload application configuration from disk.")]
    public static string ReloadConfig(
        [Description("Optional section name to reload, or empty for all")] string section = "")
    {
        // In a real app, trigger IOptionsMonitor reload or similar
        var target = string.IsNullOrEmpty(section) ? "all sections" : section;
        return $"Configuration reloaded: {target}";
    }

    [McpServerTool, Description("Check the health status of a named service dependency.")]
    public static async Task<string> CheckDependency(
        [Description("Name of the dependency to check (e.g., database, cache)")] string name,
        CancellationToken cancellationToken = default)
    {
        await Task.Delay(50, cancellationToken); // simulate check
        return $"{name}: healthy";
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxConnections = 100,
            CacheTtlSeconds = 300,
            Features = new { DarkMode = true, BetaAccess = false }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "Service Endpoints",
        MimeType = "application/json"),
     Description("Returns the configured service endpoint URLs.")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Api = "https://api.example.com/v2",
            Auth = "https://auth.example.com",
            Storage = "https://storage.example.com"
        };
        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

